package com.campus.helpdesk.controller;import com.campus.helpdesk.model.Faculty;import com.campus.helpdesk.model.User;import com.campus.helpdesk.service.FacultyService;import com.campus.helpdesk.service.UserService;import jakarta.servlet.http.HttpSession;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestParam;import org.springframework.dao.DataIntegrityViolationException;import java.util.List;@Controllerpublic class UserController {    @Autowired    private UserService userService;    @Autowired    private FacultyService facultyService;    private User checkAdminAuth(HttpSession session) {        User user = (User) session.getAttribute("loggedUser");        if (user != null && ("ADMIN".equalsIgnoreCase(user.getRole()) || "SUPER_ADMIN".equalsIgnoreCase(user.getRole()))) {            return user;        }        return null;    }    @GetMapping("/admin/users")    public String listUsers(HttpSession session, Model model) {        if (checkAdminAuth(session) == null) return "redirect:/login";        List<User> userList = userService.getAllUsers();        List<Faculty> facultyList = facultyService.getAllFaculties();        model.addAttribute("userList", userList);        model.addAttribute("facultyList", facultyList);        return "manage_users";    }    @GetMapping("/admin/users/toggleStatus")    public String toggleStatus(@RequestParam("id") int userId,                               @RequestParam("status") String currentStatus,                               HttpSession session) {        User loggedUser = checkAdminAuth(session);        if (loggedUser == null) return "redirect:/login";        String newStatus = "ACTIVE".equalsIgnoreCase(currentStatus) ? "INACTIVE" : "ACTIVE";        userService.updateUserStatus(userId, newStatus, loggedUser.getRole());        return "redirect:/admin/users";    }    @GetMapping("/admin/users/delete")    public String deleteUser(@RequestParam("id") int userId, HttpSession session) {        User loggedUser = checkAdminAuth(session);        if (loggedUser == null) return "redirect:/login";        try {            userService.deleteUser(userId, loggedUser.getRole());            return "redirect:/admin/users";        } catch (DataIntegrityViolationException e) {            return "redirect:/admin/users?error=deleteFailed";        } catch (Exception e) {            return "redirect:/admin/users?error=deleteFailed";        }    }    @GetMapping("/admin/users/checkEmail")    @org.springframework.web.bind.annotation.ResponseBody    public java.util.Map<String, Boolean> checkEmail(@RequestParam("email") String email) {        boolean exists = userService.isEmailExists(email);        java.util.Map<String, Boolean> response = new java.util.HashMap<>();        response.put("exists", exists);        return response;    }    @GetMapping("/admin/users/checkNic")    @org.springframework.web.bind.annotation.ResponseBody    public java.util.Map<String, Boolean> checkNic(@RequestParam("nic") String nic) {        boolean exists = userService.isNicExists(nic);        java.util.Map<String, Boolean> response = new java.util.HashMap<>();        response.put("exists", exists);        return response;    }    @PostMapping("/admin/users/add")    public String addUser(@RequestParam("fullName") String fullName,                          @RequestParam("email") String email,
                          @RequestParam("nic") String nic,                          @RequestParam("password") String password,                          @RequestParam("role") String role,                          @RequestParam(value = "facultyId", required = false) Integer facultyId,                          HttpSession session) {        User loggedUser = checkAdminAuth(session);        if (loggedUser == null) return "redirect:/login";        if (email == null || email.trim().isEmpty() || !email.matches("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$")) {            return "redirect:/admin/users?error=invalidEmail";        }        if (fullName == null || fullName.trim().isEmpty()) {            return "redirect:/admin/users?error=invalidData";        }        if (userService.isEmailExists(email)) {            return "redirect:/admin/users?error=emailExists";        }        if ("ADMIN".equalsIgnoreCase(role) || "SUPER_ADMIN".equalsIgnoreCase(role)) {            facultyId = 0;        } else if (facultyId == null) {            facultyId = 0;        }        User newUser = new User();        newUser.setFullName(fullName);        newUser.setEmail(email.trim());        newUser.setNic(nic.trim());        newUser.setPasswordHash(password);        newUser.setRole(role);        Faculty f = new Faculty();        f.setFacultyId(facultyId);        newUser.setFaculty(f);        boolean added = userService.addUser(newUser, loggedUser.getRole());        if (!added) {            return "redirect:/admin/users?error=emailExists";        }        return "redirect:/admin/users";    }    @PostMapping("/user/changePassword")    public String changePassword(@RequestParam("oldPassword") String oldPassword,                                 @RequestParam("newPassword") String newPassword,                                 HttpSession session) {        User loggedUser = (User) session.getAttribute("loggedUser");        if (loggedUser == null) return "redirect:/login";        boolean isUpdated = userService.changePassword(loggedUser.getUserId(), oldPassword, newPassword);        if (isUpdated) {            session.invalidate();            return "redirect:/login?msg=PasswordChanged";        } else {            String redirectUrl = "redirect:/admin/dashboard";            if ("STUDENT".equalsIgnoreCase(loggedUser.getRole())) {                redirectUrl = "redirect:/student/ticket/dashboard";            } else if ("STAFF".equalsIgnoreCase(loggedUser.getRole())) {                redirectUrl = "redirect:/staff/dashboard";            }            return redirectUrl + "?error=InvalidOldPassword";        }    }}